                <h1 id="chat-members">Chat Members</h1>

    <p>Member management for groups and channels (direct chats have no member management).</p>
<p>Rules:</p>
<ul>
<li>list    : any member of a group; admins/owner only for channels (subscribers are private).</li>
<li>add     : admins / owner.</li>
<li>role    : owner only (admin &lt;-&gt; normal). The owner's role never changes.</li>
<li>remove  : admins can remove normal members; only the owner can remove admins.
Nobody removes the owner or themselves (use DELETE /chats/{id} to leave).</li>
</ul>

                                <h2 id="chat-members-GETapi-chats--chatId--members">Paginated member list: owner first, then admins, then everyone else by name.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-GETapi-chats--chatId--members">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://127.0.0.1:8000/api/chats/1/members" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"role\": \"normal\",
    \"sort\": \"role\",
    \"direction\": \"desc\"
}"
</code></pre></div>


