                <h1 id="chats">Chats</h1>

    <p>Chat types:</p>
<ul>
<li>direct  : two users, addressed by the peer's username.</li>
<li>group   : many users, everyone can post (unless is_readonly).</li>
<li>channel : many users, only admins / the owner can post.</li>
</ul>

