<small class="badge badge-darkred">requires authentication</small>
</p>



<span id="example-requests-POSTapi-messages-direct--username-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://127.0.0.1:8000/api/messages/direct/architecto" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "content=message"\
    --form "reply_to_id=16"\
    --form "forwarded_from_message_id=16"\
    --form "attachments[0]=@/tmp/php4qbIyE" \
    --form "attachments[1]=@/tmp/phpGEobSU" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/messages/direct/architecto"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('content', 'message');
body.append('reply_to_id', '16');
body.append('forwarded_from_message_id', '16');
body.append('attachments[0]', document.querySelector('input[name="attachments[0]"]').files[0]);
body.append('attachments[1]', document.querySelector('input[name="attachments[1]"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

